#!/usr/bin/env node
// Traveler's Course content generator.
//
// Fills traveler_lesson_content for every lesson (or a filtered subset)
// with:
//   • Scene setter (2nd-person immersive description + Unsplash-quality
//     hero image generated by SDXL on Replicate)
//   • Sign / menu / notice authored in the target language, styled by
//     the runner (airport_blue | menu_card | street | notice | neon)
//   • 5 key phrases with phonetic + English + memory tip + grammar
//   • 6–8 line dialogue between traveler and local
//   • 4 exercises (multiple choice / fill blank / listening)
//
// Content is authored per lesson via Claude Sonnet 4.6 with a cached
// system prompt, then written back to Supabase over the REST API. Hero
// images are generated by Replicate's stability-ai/sdxl and the
// returned URL is saved to the scene row's `image_url` column
// (traveler_lessons does NOT have a cover_image_url column — the
// scene section is where the runner actually reads the hero image
// from).
//
// USAGE
//   node --env-file=.env.local scripts/generate-traveler-content.mjs [flags]
//
// Defaults to --dry-run and --skip-images. Live writes require --live
// AND SUPABASE_SERVICE_ROLE_KEY. Image generation requires REPLICATE_API_TOKEN
// and dropping the --skip-images flag.
//
// FLAGS
//   --dry-run              default: calls Anthropic but doesn't write to DB
//   --live                 actually write; requires SUPABASE_SERVICE_ROLE_KEY
//   --skip-images          default: skip Replicate; text content only
//   --with-images          call Replicate to generate + save hero images
//   --city <name>          limit to one city (Madrid, Paris, "Buenos Aires", …)
//   --lesson <N>           limit to lessons with this order_index
//   --limit <N>            cap the total number of lessons processed
//   --resume               skip lessons already in progress log (default on)
//   --no-resume            regenerate everything, ignoring progress
//   --reset                wipe progress log and start fresh
//   --sleep-ms <N>         delay between lessons (default 500ms)
//   --verbose              print full JSON per lesson in dry-run
//
// REQUIRED ENV
//   NEXT_PUBLIC_SUPABASE_URL, NEXT_PUBLIC_SUPABASE_ANON_KEY (dry-run reads)
//   SUPABASE_SERVICE_ROLE_KEY (only for --live writes)
//   ANTHROPIC_API_KEY
//   REPLICATE_API_TOKEN (only for --with-images)

import { readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname } from "node:path";
import { existsSync } from "node:fs";

// ---------- constants ----------

const MODEL = "claude-sonnet-4-6";
const ANTHROPIC_URL = "https://api.anthropic.com/v1/messages";
const REPLICATE_PREDICTIONS_URL = "https://api.replicate.com/v1/predictions";
const REPLICATE_MODEL_OWNER = "stability-ai";
const REPLICATE_MODEL_NAME = "sdxl";
const PROGRESS_PATH = new URL("./.traveler-content-progress.json", import.meta.url).pathname;

// One landscape aspect ratio for every hero. SDXL trained natively at
// 1024x1024 but supports 1152x896 landscape. next/image object-cover
// crops whatever comes back.
const IMAGE_WIDTH = 1152;
const IMAGE_HEIGHT = 896;

// Language + regional voice per city so accents match the geography.
const CITY_LOCALE = {
  Madrid:         { language: "spanish", region: "European Spanish (Castilian)",     speechLang: "es-ES", cultural: "peninsular Spain, formal ustedeo, uses vosotros in plural" },
  Barcelona:      { language: "spanish", region: "European Spanish (Castilian)",     speechLang: "es-ES", cultural: "peninsular Spain, signage often bilingual Catalan+Spanish" },
  "Mexico City":  { language: "spanish", region: "Mexican Spanish",                   speechLang: "es-MX", cultural: "Mexican, uses ustedeo, common regionalism 'chido' etc." },
  "Buenos Aires": { language: "spanish", region: "Rioplatense Spanish (Argentine)",   speechLang: "es-AR", cultural: "Argentine, voseo (vos in place of tú), 'sh' pronunciation of ll/y, 'che' as filler" },
  Paris:          { language: "french",  region: "Metropolitan French",               speechLang: "fr-FR", cultural: "Parisian French, formality opens with bonjour, vous by default" },
  Lyon:           { language: "french",  region: "Metropolitan French",               speechLang: "fr-FR", cultural: "same as Paris, Lyonnais gastronomy references" },
  Montreal:       { language: "french",  region: "Québécois French",                  speechLang: "fr-CA", cultural: "Québec French, bilingual bonjour-hi, Canadianisms" },
};

// Runner sign-style hint → what kind of physical signage the lesson
// depicts. Mapped from lesson location keywords; falls back to notice.
function pickSignStyle(location, lessonType, title) {
  const l = (location + " " + title).toLowerCase();
  if (/airport|airline|terminal|barajas|prat|aicm|ezeiza|cdg|trudeau|saint.?exupéry|check-in|duty free|gate|migración|migraciones|immigration|departures|arrivals|arrivées|départs|salidas|llegadas/.test(l)) return "airport_blue";
  if (/restaurant|café|cafe|bistro|bouchon|parrilla|cantina|bar |tapas|pizza|menu|comida|dinner|lunch|breakfast|chocolate|chilaquiles|bagel|poutine|caña|kir|vermut|mezcal|beaujolais|caribou|fernet|wine|cerveza|pulquería|microbrasserie/.test(l)) return "menu_card";
  if (/street|avenue|rambla|reforma|9 de julio|champs|rue|sainte-catherine|gran vía|rambla|calle|paseo|place bellecour/.test(l)) return "street";
  if (/nightclub|club |milonga|jazz|opium|pachá|rex club|bell centre|azteca|bernabéu|camp nou|bombonera|parc des princes|groupama|cinema|cinemex|cines|pathé|ugc|cineplex|flamenco/.test(l)) return "neon";
  return "notice";
}

// SDXL image prompt template. Grounded, photographic, avoids text.
function buildImagePrompt(city, country, title, location, style) {
  const styleHint = {
    airport_blue: "modern airport terminal interior, blue directional signage, travelers with luggage",
    menu_card:    "warm restaurant interior, hand-written menu on a chalkboard or wooden card, cozy lighting",
    street:       "atmospheric street view, storefronts, pedestrians, everyday city life",
    notice:       "detailed slice of daily city life, real place, natural framing",
    neon:         "evening scene with neon signage glow, city lights, atmospheric",
  }[style] || "atmospheric city scene";
  return [
    "photorealistic photograph",
    `${title.toLowerCase()} scene`,
    `${location}, ${city}, ${country}`,
    styleHint,
    "natural lighting",
    "documentary photography",
    "shot on a full-frame camera at 35mm, high detail, magazine quality",
    "no visible text, no watermarks, no signs with words",
  ].join(", ");
}

// ---------- CLI ----------

function parseArgs(argv) {
  const flags = {
    dryRun: true,
    live: false,
    withImages: false,
    resume: true,
    reset: false,
    verbose: false,
    city: null,
    lesson: null,
    limit: null,
    sleepMs: 500,
  };
  for (let i = 2; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--dry-run") { flags.dryRun = true; flags.live = false; }
    else if (a === "--live") { flags.live = true; flags.dryRun = false; }
    else if (a === "--skip-images") { flags.withImages = false; }
    else if (a === "--with-images") { flags.withImages = true; }
    else if (a === "--resume") { flags.resume = true; }
    else if (a === "--no-resume") { flags.resume = false; }
    else if (a === "--reset") { flags.reset = true; }
    else if (a === "--verbose") { flags.verbose = true; }
    else if (a === "--city") { flags.city = argv[++i]; }
    else if (a === "--lesson") { flags.lesson = parseInt(argv[++i], 10); }
    else if (a === "--limit") { flags.limit = parseInt(argv[++i], 10); }
    else if (a === "--sleep-ms") { flags.sleepMs = parseInt(argv[++i], 10); }
    else { console.error(`unknown flag: ${a}`); process.exit(1); }
  }
  return flags;
}

function requireEnv(name) {
  const v = process.env[name];
  if (!v) {
    console.error(`Missing env: ${name}`);
    process.exit(1);
  }
  return v;
}

// ---------- retry ----------

async function withRetry(label, fn, { maxAttempts = 5, baseDelayMs = 800 } = {}) {
  let lastErr;
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try { return await fn(); }
    catch (err) {
      lastErr = err;
      const retryable = err?.retryable === true;
      if (!retryable || attempt === maxAttempts) throw err;
      const delay = baseDelayMs * Math.pow(2, attempt - 1);
      console.error(`[retry] ${label} attempt ${attempt} failed (${err.message}); waiting ${delay}ms`);
      await new Promise((r) => setTimeout(r, delay));
    }
  }
  throw lastErr;
}
function markRetryable(err) { err.retryable = true; return err; }

// ---------- Supabase ----------

function makeSupabase({ url, key }) {
  const base = url.replace(/\/$/, "");
  const headers = { apikey: key, Authorization: `Bearer ${key}`, "Content-Type": "application/json" };
  async function req(method, path, { body, prefer } = {}) {
    const res = await fetch(`${base}/rest/v1${path}`, {
      method,
      headers: { ...headers, ...(prefer ? { Prefer: prefer } : {}) },
      body: body ? JSON.stringify(body) : undefined,
    });
    if (!res.ok) {
      const text = await res.text().catch(() => "");
      const err = new Error(`supabase ${method} ${path} ${res.status}: ${text.slice(0, 300)}`);
      if (res.status === 429 || res.status >= 500) markRetryable(err);
      throw err;
    }
    if (res.status === 204) return null;
    return res.json();
  }
  return {
    get:    (path)        => withRetry(`GET ${path}`,    () => req("GET",    path)),
    post:   (path, body)  => withRetry(`POST ${path}`,   () => req("POST",   path, { body, prefer: "return=representation" })),
    delete: (path)        => withRetry(`DELETE ${path}`, () => req("DELETE", path)),
  };
}

// ---------- Anthropic ----------

const SYSTEM_PROMPT = `You are an expert language-content author for an immersive traveler's course app called Languages Center. You write realistic, culturally accurate lesson content for travelers landing in a specific city.

For every lesson you receive a city, country, lesson title, location, lesson_type, order_index, and a list of vocabulary from previous lessons in the same city. You produce a single JSON object with these sections, all authored from a traveler's point of view:

1. scene — an immersive 2-3 sentence description in the SECOND PERSON ("You've just landed…"). Reference the actual place, the sensory details a traveler would notice, and the language they're about to hear. Use **markdown bold** sparingly for real place names.

2. scene_image_prompt — a detailed SDXL prompt (~30 words) for a photorealistic hero image of this scene. Ground it in the specific city. Avoid depicting readable text (SDXL hallucinates text).

3. scene_stamp — a very short label (2-6 chars) for the travel-stamp overlay, e.g. "MADRID", "CDG", "TAXI", "BAR". Uppercase.

4. scene_stamp_sublabel — subtitle for the stamp, e.g. "MAD · BARAJAS T4", "CDG → LE MARAIS", "SAN TELMO 22:15". Uppercase, terse.

5. sign — a realistic sign, menu item, notice, or display that a traveler would actually see at this exact location. Authored in the TARGET LANGUAGE as it would authentically appear. Include:
   - style: one of "airport_blue" | "menu_card" | "street" | "notice" | "neon" — depends on the physical medium
   - title: the main line of the sign, in target-language ALL CAPS (except menu items which use natural capitalization)
   - subtitle: optional English translation OR secondary target-language line
   - icon: optional short symbol like "→", "✈", "€", or null
   - note: one sentence in English describing where in the location this sign is (e.g. "Overhead sign after immigration.")
   - words: 3-5 clickable words FROM THE SIGN, each with { text, phonetic, english, tip }. Phonetic uses a plain-English respelling (not IPA). Tip is one sentence — a memory hook or etymology.

6. phrases — exactly 5 essential phrases a traveler will need for this specific location. Each: { phrase, phonetic, english, tip, grammar }.
   - phrase: natural, spoken target-language phrase — not a textbook sentence
   - phonetic: plain-English respelling
   - english: idiomatic translation
   - tip: one-sentence memory trick or usage note
   - grammar: brief per-phrase grammar hint

7. grammar_note — a plain-English paragraph explaining ONE structural feature that ties these phrases together (verb tense, formality register, contraction, word order). Written for a beginner, no jargon.

8. dialogue — 6-11 lines of realistic conversation between a "You" (the traveler) and one or more locals appropriate to the location (Officer, Waiter, Driver, Concierge, etc). Aim for 6-8 in tightly-scoped situations (hotel check-in, buying a ticket) and 8-11 in richer social exchanges (small talk, invitations, misunderstandings). Each line: { speaker, target, english }.
   - speaker: short role label, always "You" for the traveler
   - target: what's said in the target language, natural and idiomatic to the region
   - english: idiomatic translation

9. quiz — exactly 4 exercises testing this lesson's content. Each: { type, question, correct_answer, wrong_answers, translation, audio_prompt }.
   - type: "multiple_choice" | "fill_blank" | "listening"
   - question: English (or a mix — for fill_blank, embed the target-language sentence with a ___ blank)
   - correct_answer: the target-language answer for fill_blank/listening, or the English answer for multiple_choice comprehension
   - wrong_answers: 3 plausible distractors from the SAME semantic field. Same language as correct_answer.
   - translation: for fill_blank/listening, the English translation of the correct_answer. Null for multiple_choice.
   - audio_prompt: for listening only — the target-language phrase to play aloud. Null for other types.
   Mix the types: at least one multiple_choice, one fill_blank, and one listening.

VOCABULARY DISCIPLINE
Use ONLY vocabulary that appears in this lesson (sign, phrases, dialogue) or in the "previously seen vocabulary" list provided. Never introduce new words in the quiz that don't appear elsewhere in the lesson.

CULTURAL AUTHENTICITY
Match the regional variety. Madrid = European Spanish with vosotros; Buenos Aires = Rioplatense with vos and "che"; Mexico City = Mexican Spanish; Paris/Lyon = Metropolitan French; Montreal = Québécois with bonjour-hi etc. Use real place names and real signage vocabulary from that country's public infrastructure.

FORMAT
Output ONLY the JSON object — no prose, no markdown code fences. All fields are required. Every string is non-empty.`;

const OUTPUT_SCHEMA = {
  type: "object",
  additionalProperties: false,
  properties: {
    scene: { type: "string" },
    scene_image_prompt: { type: "string" },
    scene_stamp: { type: "string" },
    scene_stamp_sublabel: { type: "string" },
    sign: {
      type: "object",
      additionalProperties: false,
      properties: {
        style: { type: "string", enum: ["airport_blue", "menu_card", "street", "notice", "neon"] },
        title: { type: "string" },
        subtitle: { type: ["string", "null"] },
        icon: { type: ["string", "null"] },
        note: { type: "string" },
        words: {
          type: "array",
          items: {
            type: "object",
            additionalProperties: false,
            properties: {
              text:      { type: "string" },
              phonetic:  { type: "string" },
              english:   { type: "string" },
              tip:       { type: "string" },
            },
            required: ["text", "phonetic", "english", "tip"],
          },
        },
      },
      required: ["style", "title", "subtitle", "icon", "note", "words"],
    },
    phrases: {
      type: "array",
      items: {
        type: "object",
        additionalProperties: false,
        properties: {
          phrase:   { type: "string" },
          phonetic: { type: "string" },
          english:  { type: "string" },
          tip:      { type: "string" },
          grammar:  { type: "string" },
        },
        required: ["phrase", "phonetic", "english", "tip", "grammar"],
      },
    },
    grammar_note: { type: "string" },
    dialogue: {
      type: "array",
      items: {
        type: "object",
        additionalProperties: false,
        properties: {
          speaker: { type: "string" },
          target:  { type: "string" },
          english: { type: "string" },
        },
        required: ["speaker", "target", "english"],
      },
    },
    quiz: {
      type: "array",
      items: {
        type: "object",
        additionalProperties: false,
        properties: {
          type:            { type: "string", enum: ["multiple_choice", "fill_blank", "listening"] },
          question:        { type: "string" },
          correct_answer:  { type: "string" },
          wrong_answers:   { type: "array", items: { type: "string" } },
          translation:     { type: ["string", "null"] },
          audio_prompt:    { type: ["string", "null"] },
        },
        required: ["type", "question", "correct_answer", "wrong_answers", "translation", "audio_prompt"],
      },
    },
  },
  required: ["scene", "scene_image_prompt", "scene_stamp", "scene_stamp_sublabel", "sign", "phrases", "grammar_note", "dialogue", "quiz"],
};

async function generateContent({ apiKey, city, country, lesson, locale, previousVocab, suggestedSignStyle }) {
  const userPayload = {
    city,
    country,
    language: locale.language,
    region: locale.region,
    cultural_notes: locale.cultural,
    lesson: {
      title: lesson.title,
      location: lesson.location_name,
      lesson_type: lesson.lesson_type,
      order_index: lesson.order_index,
      is_premium: lesson.is_premium,
    },
    suggested_sign_style: suggestedSignStyle,
    previously_seen_vocabulary: previousVocab,
  };
  const body = {
    model: MODEL,
    max_tokens: 8000,
    thinking: { type: "disabled" },
    output_config: {
      effort: "low",
      format: { type: "json_schema", schema: OUTPUT_SCHEMA },
    },
    system: [
      { type: "text", text: SYSTEM_PROMPT, cache_control: { type: "ephemeral" } },
    ],
    messages: [{ role: "user", content: JSON.stringify(userPayload, null, 2) }],
  };

  return withRetry(`anthropic ${city}/L${lesson.order_index}`, async () => {
    const res = await fetch(ANTHROPIC_URL, {
      method: "POST",
      headers: {
        "x-api-key": apiKey,
        "anthropic-version": "2023-06-01",
        "Content-Type": "application/json",
      },
      body: JSON.stringify(body),
    });
    if (!res.ok) {
      const text = await res.text().catch(() => "");
      const err = new Error(`anthropic ${res.status}: ${text.slice(0, 500)}`);
      if (res.status === 429 || res.status >= 500 || res.status === 529) markRetryable(err);
      throw err;
    }
    const json = await res.json();
    const textBlock = (json.content ?? []).find((b) => b.type === "text");
    if (!textBlock) throw new Error("no text block in anthropic response");
    let parsed;
    try { parsed = JSON.parse(textBlock.text); }
    catch { throw new Error(`response is not valid JSON: ${textBlock.text.slice(0, 200)}`); }
    validateContent(parsed);
    return { content: parsed, usage: json.usage ?? null };
  });
}

// Anthropic's structured-output schema doesn't accept minItems/maxItems
// above 1, so we enforce the array sizes here after JSON parse. Anything
// off-count is retryable — the model is deterministic enough that a
// second call usually recovers.
function validateContent(ai) {
  const errs = [];
  const nWords = ai?.sign?.words?.length ?? 0;
  if (nWords < 3 || nWords > 5) errs.push(`sign.words must be 3-5, got ${nWords}`);
  const nPhrases = ai?.phrases?.length ?? 0;
  if (nPhrases !== 5) errs.push(`phrases must be exactly 5, got ${nPhrases}`);
  const nDialogue = ai?.dialogue?.length ?? 0;
  if (nDialogue < 6 || nDialogue > 11) errs.push(`dialogue must be 6-11 lines, got ${nDialogue}`);
  const nQuiz = ai?.quiz?.length ?? 0;
  if (nQuiz !== 4) errs.push(`quiz must be exactly 4, got ${nQuiz}`);
  for (const [i, q] of (ai?.quiz ?? []).entries()) {
    const nw = q?.wrong_answers?.length ?? 0;
    if (nw !== 3) errs.push(`quiz[${i}].wrong_answers must be 3, got ${nw}`);
  }
  const types = new Set((ai?.quiz ?? []).map((q) => q.type));
  if (!types.has("multiple_choice") || !types.has("fill_blank") || !types.has("listening")) {
    errs.push(`quiz must include at least one of each type; got [${Array.from(types).join(", ")}]`);
  }
  if (errs.length > 0) {
    const err = new Error(`content validation failed: ${errs.join("; ")}`);
    markRetryable(err);
    throw err;
  }
}

// ---------- Replicate (SDXL) ----------

// Cache the SDXL model version between calls so we only hit the model
// metadata endpoint once per run.
let cachedReplicateVersion = null;

async function fetchReplicateVersion(token) {
  if (cachedReplicateVersion) return cachedReplicateVersion;
  return withRetry(`replicate model lookup`, async () => {
    const res = await fetch(
      `https://api.replicate.com/v1/models/${REPLICATE_MODEL_OWNER}/${REPLICATE_MODEL_NAME}`,
      { headers: { Authorization: `Bearer ${token}` } },
    );
    if (!res.ok) {
      const text = await res.text().catch(() => "");
      const err = new Error(`replicate model lookup ${res.status}: ${text.slice(0, 400)}`);
      if (res.status === 429 || res.status >= 500) markRetryable(err);
      throw err;
    }
    const model = await res.json();
    const version = model?.latest_version?.id;
    if (!version) throw new Error("replicate model response missing latest_version.id");
    cachedReplicateVersion = version;
    return version;
  });
}

async function generateImage({ token, prompt }) {
  const version = await fetchReplicateVersion(token);
  return withRetry(`replicate`, async () => {
    // Prefer: wait=60 makes the create call synchronous when possible;
    // long-running predictions still return a URL to poll.
    const createRes = await fetch(REPLICATE_PREDICTIONS_URL, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
        Prefer: "wait=60",
      },
      body: JSON.stringify({
        version,
        input: {
          prompt,
          width: IMAGE_WIDTH,
          height: IMAGE_HEIGHT,
          num_inference_steps: 30,
          guidance_scale: 7.5,
          num_outputs: 1,
        },
      }),
    });
    if (!createRes.ok) {
      const text = await createRes.text().catch(() => "");
      const err = new Error(`replicate create ${createRes.status}: ${text.slice(0, 400)}`);
      if (createRes.status === 429 || createRes.status >= 500) markRetryable(err);
      throw err;
    }
    let pred = await createRes.json();
    // Poll until finished if the create didn't complete in the 60s window.
    while (pred.status === "starting" || pred.status === "processing") {
      await new Promise((r) => setTimeout(r, 3000));
      const pollRes = await fetch(pred.urls?.get, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!pollRes.ok) {
        const text = await pollRes.text().catch(() => "");
        const err = new Error(`replicate poll ${pollRes.status}: ${text.slice(0, 400)}`);
        if (pollRes.status === 429 || pollRes.status >= 500) markRetryable(err);
        throw err;
      }
      pred = await pollRes.json();
    }
    if (pred.status !== "succeeded") {
      throw new Error(`replicate finished with status=${pred.status} error=${JSON.stringify(pred.error)}`);
    }
    const url = Array.isArray(pred.output) ? pred.output[0] : pred.output;
    if (typeof url !== "string") throw new Error(`replicate output missing URL: ${JSON.stringify(pred.output).slice(0, 200)}`);
    return url;
  });
}

// ---------- content → DB rows ----------

function toContentRows(lessonId, ai, imageUrl) {
  // PostgREST bulk INSERT requires every object in the array to have
  // identical keys (PGRST102: "All object keys must match"). We emit
  // the full column set on every row with per-type overrides.
  const base = {
    traveler_lesson_id: lessonId,
    content_type: null,
    content_order: 0,
    image_url: null,
    image_alt: null,
    explanation_text: null,
    dialogue_lines: [],
    quiz_questions: [],
    data: {},
  };
  return [
    {
      ...base,
      content_type: "scene",
      content_order: 1,
      image_url: imageUrl,
      image_alt: `${ai.scene_stamp} scene`,
      explanation_text: ai.scene,
      data: {
        stamp: ai.scene_stamp,
        stampSublabel: ai.scene_stamp_sublabel,
      },
    },
    {
      ...base,
      content_type: "sign",
      content_order: 2,
      data: {
        style: ai.sign.style,
        title: ai.sign.title,
        subtitle: ai.sign.subtitle,
        icon: ai.sign.icon,
        note: ai.sign.note,
        words: ai.sign.words,
      },
    },
    {
      ...base,
      content_type: "phrases",
      content_order: 3,
      data: { phrases: ai.phrases, grammarNote: ai.grammar_note },
    },
    {
      ...base,
      content_type: "dialogue",
      content_order: 4,
      dialogue_lines: ai.dialogue,
    },
    {
      ...base,
      content_type: "quiz",
      content_order: 5,
      quiz_questions: ai.quiz,
    },
  ];
}

// ---------- vocab carryover ----------

// Compact list of tokens from previous lessons in the same city — fed
// back into the model so quiz distractors and re-used phrases stay
// within the learner's known vocabulary.
function harvestVocab(aiContent) {
  const tokens = new Set();
  for (const w of aiContent.sign?.words ?? []) if (w.text) tokens.add(w.text.toLowerCase().trim());
  for (const p of aiContent.phrases ?? []) if (p.phrase) tokens.add(p.phrase.toLowerCase().trim());
  return Array.from(tokens);
}

// ---------- progress ----------

async function loadProgress(reset) {
  if (reset) return { completed_lessons: {}, started_at: new Date().toISOString() };
  if (!existsSync(PROGRESS_PATH)) return { completed_lessons: {}, started_at: new Date().toISOString() };
  try { return JSON.parse(await readFile(PROGRESS_PATH, "utf-8")); }
  catch { return { completed_lessons: {}, started_at: new Date().toISOString() }; }
}
async function saveProgress(progress) {
  await mkdir(dirname(PROGRESS_PATH), { recursive: true });
  await writeFile(PROGRESS_PATH, JSON.stringify(progress, null, 2));
}

// ---------- main ----------

async function main() {
  const flags = parseArgs(process.argv);

  const supabaseUrl = requireEnv("NEXT_PUBLIC_SUPABASE_URL");
  const anonKey = requireEnv("NEXT_PUBLIC_SUPABASE_ANON_KEY");
  const anthropicKey = requireEnv("ANTHROPIC_API_KEY");
  const serviceKey = flags.live ? requireEnv("SUPABASE_SERVICE_ROLE_KEY") : null;
  const replicateToken = flags.withImages ? requireEnv("REPLICATE_API_TOKEN") : null;

  // Reads go through anon; writes go through service.
  const readClient = makeSupabase({ url: supabaseUrl, key: anonKey });
  const writeClient = flags.live ? makeSupabase({ url: supabaseUrl, key: serviceKey }) : null;

  console.log(`🌍 Traveler content generator`);
  console.log(`   mode:         ${flags.dryRun ? "DRY-RUN" : "LIVE"}`);
  console.log(`   images:       ${flags.withImages ? "ON (Replicate SDXL)" : "OFF"}`);
  console.log(`   filters:      ${flags.city ? `city=${flags.city} ` : ""}${flags.lesson ? `lesson=${flags.lesson}` : ""}${!flags.city && !flags.lesson ? "(none)" : ""}`);
  console.log(`   resume:       ${flags.resume ? "on" : "off"}${flags.reset ? " (reset)" : ""}`);
  console.log("");

  // 1. Load courses + lessons
  const courses = await readClient.get(`/traveler_courses?select=id,city,country,language_id,order_index&order=order_index.asc`);
  const activeCourses = flags.city
    ? courses.filter((c) => c.city.toLowerCase() === flags.city.toLowerCase())
    : courses;
  if (activeCourses.length === 0) {
    console.error(`No matching city found. Available: ${courses.map((c) => c.city).join(", ")}`);
    process.exit(1);
  }

  const progress = await loadProgress(flags.reset);
  let processed = 0;
  let succeeded = 0;
  let failed = 0;
  const failures = [];

  for (const course of activeCourses) {
    const locale = CITY_LOCALE[course.city];
    if (!locale) {
      console.warn(`⚠ no locale mapping for ${course.city}, skipping`);
      continue;
    }

    const lessons = await readClient.get(
      `/traveler_lessons?traveler_course_id=eq.${course.id}&select=id,title,location_name,lesson_type,order_index,is_premium,xp_reward&order=order_index.asc`,
    );

    const filteredLessons = flags.lesson
      ? lessons.filter((l) => l.order_index === flags.lesson)
      : lessons;

    if (filteredLessons.length === 0) continue;

    console.log(`\n📍 ${course.city}, ${course.country} — ${filteredLessons.length} lesson(s) queued`);

    // Vocabulary from previously-processed lessons in this city (loaded
    // from the progress log's stored tokens). Ensures quiz distractors
    // + reused phrases stay within known vocab.
    let cityVocab = [];
    for (const done of Object.values(progress.completed_lessons)) {
      if (done.city === course.city && Array.isArray(done.vocab)) {
        cityVocab.push(...done.vocab);
      }
    }
    cityVocab = Array.from(new Set(cityVocab));

    for (const lesson of filteredLessons) {
      if (flags.limit && processed >= flags.limit) {
        console.log(`\n⚑ limit ${flags.limit} reached, stopping`);
        break;
      }
      const key = `${course.city}:${lesson.order_index}`;
      if (flags.resume && progress.completed_lessons[key]?.hasContent) {
        console.log(`   ↷ skip L${lesson.order_index} ${lesson.title} (already done)`);
        continue;
      }
      processed++;

      const suggestedStyle = pickSignStyle(lesson.location_name, lesson.lesson_type, lesson.title);
      const t0 = Date.now();
      try {
        // 1. Anthropic content
        const { content: ai, usage } = await generateContent({
          apiKey: anthropicKey,
          city: course.city,
          country: course.country,
          lesson,
          locale,
          previousVocab: cityVocab.slice(0, 300), // cap so the prompt stays small
          suggestedSignStyle: suggestedStyle,
        });

        // 2. Replicate image
        let imageUrl = null;
        if (flags.withImages) {
          const imgPrompt = ai.scene_image_prompt || buildImagePrompt(course.city, course.country, lesson.title, lesson.location_name, ai.sign.style);
          imageUrl = await generateImage({ token: replicateToken, prompt: imgPrompt });
        }

        const rows = toContentRows(lesson.id, ai, imageUrl);
        const elapsed = ((Date.now() - t0) / 1000).toFixed(1);

        if (flags.dryRun) {
          console.log(`\n─── L${lesson.order_index}  ${lesson.title}  (${elapsed}s${usage ? `, in=${usage.input_tokens ?? "?"} out=${usage.output_tokens ?? "?"}` : ""}) ───`);
          if (flags.verbose) {
            console.log(JSON.stringify({ ai, rows }, null, 2));
          } else {
            console.log(`  scene:   ${ai.scene.slice(0, 100)}${ai.scene.length > 100 ? "…" : ""}`);
            console.log(`  stamp:   ${ai.scene_stamp} · ${ai.scene_stamp_sublabel}`);
            console.log(`  sign:    [${ai.sign.style}] "${ai.sign.title}"  (${ai.sign.words.length} clickable words)`);
            console.log(`  phrases: ${ai.phrases.length}   e.g. "${ai.phrases[0].phrase}"`);
            console.log(`  grammar: ${ai.grammar_note.slice(0, 120)}${ai.grammar_note.length > 120 ? "…" : ""}`);
            console.log(`  dialog:  ${ai.dialogue.length} lines`);
            console.log(`  quiz:    ${ai.quiz.length} questions [${ai.quiz.map(q => q.type).join(", ")}]`);
            console.log(`  image:   ${imageUrl ?? "(skipped)"}`);
          }
        } else {
          // Replace: delete existing content, insert fresh
          await writeClient.delete(`/traveler_lesson_content?traveler_lesson_id=eq.${lesson.id}`);
          await writeClient.post(`/traveler_lesson_content`, rows);
          console.log(`   ✓ L${lesson.order_index} ${lesson.title} (${elapsed}s${imageUrl ? " + image" : ""})`);
        }

        // Update vocab pool + progress
        const newVocab = harvestVocab(ai);
        cityVocab = Array.from(new Set([...cityVocab, ...newVocab]));
        progress.completed_lessons[key] = {
          city: course.city,
          order: lesson.order_index,
          hasContent: !flags.dryRun,
          hasImage: !!imageUrl && !flags.dryRun,
          vocab: newVocab,
          timestamp: new Date().toISOString(),
        };
        if (!flags.dryRun) await saveProgress(progress);

        succeeded++;
      } catch (err) {
        failed++;
        failures.push({ city: course.city, lesson: lesson.order_index, title: lesson.title, error: err.message });
        console.error(`   ✗ L${lesson.order_index} ${lesson.title}: ${err.message}`);
      }

      if (flags.sleepMs > 0) await new Promise((r) => setTimeout(r, flags.sleepMs));
    }
    if (flags.limit && processed >= flags.limit) break;
  }

  console.log("\n═══════════════════════════════════════════");
  console.log(`Done. processed=${processed} succeeded=${succeeded} failed=${failed}`);
  if (failures.length > 0) {
    console.log("\nFailures:");
    for (const f of failures) console.log(`  ${f.city}/L${f.lesson} — ${f.title}: ${f.error}`);
  }
  if (!flags.dryRun) console.log(`Progress log: ${PROGRESS_PATH}`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
